import{_ as t,o as s,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"《正交》物理公式与推导精要","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/culture/orthogonal-physics-formulas.md","filePath":"topics/culture/orthogonal-physics-formulas.md"}'),i={name:"topics/culture/orthogonal-physics-formulas.md"};function l(p,a,o,d,r,h){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="《正交》物理公式与推导精要" tabindex="-1">《正交》物理公式与推导精要 <a class="header-anchor" href="#《正交》物理公式与推导精要" aria-label="Permalink to &quot;《正交》物理公式与推导精要&quot;">​</a></h1><blockquote><p>来源：Greg Egan 官网 &quot;Plus, Minus: A Gentle Introduction to the Physics of Orthogonal&quot; 原文：<a href="https://www.gregegan.net/ORTHOGONAL/00/PM.html" target="_blank" rel="noreferrer">https://www.gregegan.net/ORTHOGONAL/00/PM.html</a> 本文提取了 Egan 的完整数学推导，作为对三部曲物理设定的精确参考。</p></blockquote><hr><h2 id="一、毕达哥拉斯定理的双面版本-the-dual-pythagorean-theorem" tabindex="-1">一、毕达哥拉斯定理的双面版本（The Dual Pythagorean Theorem） <a class="header-anchor" href="#一、毕达哥拉斯定理的双面版本-the-dual-pythagorean-theorem" aria-label="Permalink to &quot;一、毕达哥拉斯定理的双面版本（The Dual Pythagorean Theorem）&quot;">​</a></h2><h3 id="我们的宇宙-洛伦兹几何-lorentzian" tabindex="-1">我们的宇宙（洛伦兹几何 / Lorentzian） <a class="header-anchor" href="#我们的宇宙-洛伦兹几何-lorentzian" aria-label="Permalink to &quot;我们的宇宙（洛伦兹几何 / Lorentzian）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时空间隔的不变量：s² = x² - t²</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三个分类：</span></span>
<span class="line"><span>  x² - t² &lt; 0  → 类时间隔（timelike）→ 普通物体的世界线</span></span>
<span class="line"><span>  x² - t² &gt; 0  → 类空间隔（spacelike）→ 不能通过实体连接</span></span>
<span class="line"><span>  x² - t² = 0  → 类光间隔（null）→ 光的世界线</span></span></code></pre></div><h3 id="正交宇宙-黎曼几何-riemannian" tabindex="-1">正交宇宙（黎曼几何 / Riemannian） <a class="header-anchor" href="#正交宇宙-黎曼几何-riemannian" aria-label="Permalink to &quot;正交宇宙（黎曼几何 / Riemannian）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时空间隔的不变量：s² = x² + t²</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当 s &gt; 0 时，没有类时/类空/类光的区分</span></span>
<span class="line"><span>所有方向本质上相同</span></span>
<span class="line"><span>&quot;东&quot;和&quot;未来&quot;没有根本区别</span></span></code></pre></div><h3 id="四维向量的点积对比" tabindex="-1">四维向量的点积对比 <a class="header-anchor" href="#四维向量的点积对比" aria-label="Permalink to &quot;四维向量的点积对比&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>洛伦兹点积（我们的宇宙）：</span></span>
<span class="line"><span>  v · w = vx·wx + vy·wy + vz·wz - vt·wt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>黎曼点积（正交宇宙）：</span></span>
<span class="line"><span>  v · w = vx·wx + vy·wy + vz·wz + vt·wt</span></span></code></pre></div><p><strong>核心差异</strong>：± 号一个符号的改变，颠覆了整个物理学。</p><hr><h2 id="二、几何与运动-geometry-and-motion" tabindex="-1">二、几何与运动（Geometry and Motion） <a class="header-anchor" href="#二、几何与运动-geometry-and-motion" aria-label="Permalink to &quot;二、几何与运动（Geometry and Motion）&quot;">​</a></h2><h3 id="四速度-four-velocity" tabindex="-1">四速度（Four-velocity） <a class="header-anchor" href="#四速度-four-velocity" aria-label="Permalink to &quot;四速度（Four-velocity）&quot;">​</a></h3><p><strong>定义</strong>：单位向量 u，与世界线相切，长度为 1。</p><p><strong>普通（三维）速度的导出</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vx = ux / ut</span></span></code></pre></div><h3 id="四加速度-four-acceleration" tabindex="-1">四加速度（Four-acceleration） <a class="header-anchor" href="#四加速度-four-acceleration" aria-label="Permalink to &quot;四加速度（Four-acceleration）&quot;">​</a></h3><p><strong>定义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a = ∂τ u    （四速度对固有时 τ 的导数）</span></span></code></pre></div><p><strong>关键性质</strong>：四加速度与四速度正交（垂直）。</p><ul><li>四速度 u 始终是单位向量，长度不变</li><li>唯一可能的变化是方向</li><li>因此 a ⟂ u（a 与 u 正交）</li></ul><h3 id="恒定加速度下的世界线" tabindex="-1">恒定加速度下的世界线 <a class="header-anchor" href="#恒定加速度下的世界线" aria-label="Permalink to &quot;恒定加速度下的世界线&quot;">​</a></h3><p>在我们的宇宙中，恒定加速的物体永远无法达到光速。 在正交宇宙中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>恒定加速度 a 的物体在 xt 平面中的轨迹是圆弧！</span></span>
<span class="line"><span></span></span>
<span class="line"><span>x(τ) = (1/a)(1 - cos(aτ), sin(aτ))</span></span>
<span class="line"><span>u(τ) = ∂τ x(τ) = (sin(aτ), cos(aτ))</span></span>
<span class="line"><span>a(τ) = ∂τ u(τ) = a(cos(aτ), -sin(aτ))</span></span></code></pre></div><p><strong>后果</strong>：</p><ul><li>经过有限时间 t = 1/a，物体会达到<strong>无穷大速度</strong></li><li>随后会在我们的坐标中<strong>倒退时间</strong></li><li>这说明了：时间在正交宇宙中只是观察者的选择</li></ul><h3 id="能量-动量向量" tabindex="-1">能量-动量向量 <a class="header-anchor" href="#能量-动量向量" aria-label="Permalink to &quot;能量-动量向量&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P = m u    （能量-动量 = 质量 × 四速度）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>分量表示（在 xt 平面中）：</span></span>
<span class="line"><span>  Pt = E（总能量）</span></span>
<span class="line"><span>  Px = p（动量）</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>长度恒等式：</span></span>
<span class="line"><span>  m² = |P|² = E² + p²</span></span></code></pre></div><h3 id="能量和动量公式" tabindex="-1">能量和动量公式 <a class="header-anchor" href="#能量和动量公式" aria-label="Permalink to &quot;能量和动量公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>由 v = p/E 和 m² = E² + p² 推导：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>E = m / √(1 + v²)</span></span>
<span class="line"><span>p = m v / √(1 + v²)</span></span></code></pre></div><p><strong>对比</strong>：</p><table tabindex="0"><thead><tr><th>物理量</th><th>牛顿力学</th><th>洛伦兹（我们的宇宙）</th><th>黎曼（正交宇宙）</th></tr></thead><tbody><tr><td>E</td><td>m + ½mv²</td><td>m / √(1 - v²)</td><td>m / √(1 + v²)</td></tr><tr><td>p</td><td>mv</td><td>mv / √(1 - v²)</td><td>mv / √(1 + v²)</td></tr><tr><td>动能 K</td><td>½mv²</td><td>m(1/√(1-v²) - 1)</td><td>m(1 - 1/√(1+v²))</td></tr></tbody></table><h3 id="动能的符号反转" tabindex="-1">动能的符号反转 <a class="header-anchor" href="#动能的符号反转" aria-label="Permalink to &quot;动能的符号反转&quot;">​</a></h3><p><strong>关键公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E ≈ m - ½mv²    （低速近似）</span></span>
<span class="line"><span>K = m - E = m(1 - 1/√(1+v²))</span></span></code></pre></div><p>在我们的宇宙中：总能量 = 静止质量 + 动能（正）。 在正交宇宙中：总能量 = 静止质量 - 动能（负）。</p><p><strong>通俗理解</strong>：</p><ul><li>在我们的宇宙中：物体运动越快，总能量越大</li><li>在正交宇宙中：物体运动越快，总能量越小（因为动能贡献为负）</li><li>低速时，这个差异不明显（因为 ½mv² 很小）</li><li>只有在涉及光或粒子产生的高能过程中，差异才会显现</li></ul><h3 id="光的无家可归" tabindex="-1">光的无家可归 <a class="header-anchor" href="#光的无家可归" aria-label="Permalink to &quot;光的无家可归&quot;">​</a></h3><p>在我们的宇宙中，光满足：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E = p（无静止质量，m = 0）</span></span></code></pre></div><p>在正交宇宙中，光必须有静止质量 m &gt; 0 才能有 E &gt; 0：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E² = m² - p²</span></span></code></pre></div><p><strong>光的创造</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在正交宇宙中创造光 = 系统动能增加！</span></span>
<span class="line"><span>物质释放光 → 系统获得动能 → 物质加速</span></span></code></pre></div><hr><h2 id="三、能量守恒-conservation-laws" tabindex="-1">三、能量守恒（Conservation Laws） <a class="header-anchor" href="#三、能量守恒-conservation-laws" aria-label="Permalink to &quot;三、能量守恒（Conservation Laws）&quot;">​</a></h2><h3 id="黎曼版本的守恒定律" tabindex="-1">黎曼版本的守恒定律 <a class="header-anchor" href="#黎曼版本的守恒定律" aria-label="Permalink to &quot;黎曼版本的守恒定律&quot;">​</a></h3><p>不依赖参考系的表述：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在相互作用后，沿所有世界线离开的箭头（能量-动量向量）之和为零。</span></span></code></pre></div><p><strong>奇怪的结果</strong>：</p><ul><li>同一个碰撞，不同观察者看到不同的粒子数</li><li>一个观察者看到：两粒子碰撞 → 两粒子弹开</li><li>另一个观察者看到：三粒子碰撞 → 一粒子离开（包含反物质湮灭）</li><li><strong>两个描述都是正确的</strong>——取决于&quot;时间轴&quot;的选择</li></ul><hr><h2 id="四、延续的物理章节" tabindex="-1">四、延续的物理章节 <a class="header-anchor" href="#四、延续的物理章节" aria-label="Permalink to &quot;四、延续的物理章节&quot;">​</a></h2><p>Egan 的页面还包含后续章节，但未被这只蜘蛛爬取：</p><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><strong>Geometry and Waves</strong></td><td>光在黎曼几何中的传播，色散关系</td></tr><tr><td><strong>Riemannian Electromagnetism</strong></td><td>麦克斯韦方程组的黎曼版本</td></tr><tr><td><strong>Riemannian Thermodynamics</strong></td><td>热力学定律的黎曼版本</td></tr><tr><td><strong>Riemannian General Relativity</strong></td><td>爱因斯坦场方程的黎曼版本</td></tr><tr><td><strong>Riemannian Quantum Mechanics</strong></td><td>薛定谔方程的黎曼版本</td></tr></tbody></table><p>每章节都有对应的完整数学推导，感兴趣的可以从 Egan 官网直接阅读。</p><hr><h2 id="五、公式速查表" tabindex="-1">五、公式速查表 <a class="header-anchor" href="#五、公式速查表" aria-label="Permalink to &quot;五、公式速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>物理概念</th><th>我们的宇宙</th><th>正交宇宙</th></tr></thead><tbody><tr><td>不变量</td><td>x² - t²</td><td>x² + t²</td></tr><tr><td>点积</td><td>-vt·wt</td><td>+vt·wt</td></tr><tr><td>光速</td><td>恒定 c</td><td>取决于波长</td></tr><tr><td>光速极限</td><td>v &lt; 1（无法达到）</td><td>v 无上限（可达无穷大）</td></tr><tr><td>总能量公式</td><td>E = m/√(1-v²)</td><td>E = m/√(1+v²)</td></tr><tr><td>动能</td><td>正（运动→能量↑）</td><td>负（运动→能量↓）</td></tr><tr><td>光的静止质量</td><td>0</td><td>&gt; 0</td></tr><tr><td>加速极限</td><td>无法超光速</td><td>可达无穷速然后&quot;倒退时间&quot;</td></tr><tr><td>时间箭头</td><td>客观（热力学第二定律）</td><td>观察者选择（熵增方向）</td></tr><tr><td>因果结构</td><td>光锥定义过去/未来</td><td>无光锥，所有方向等价</td></tr></tbody></table><hr><blockquote><p>关键词：毕达哥拉斯定理、洛伦兹点积、黎曼点积、四速度、四加速度、能量-动量、动能负值、光速不恒定、质量缺陷反转、时间无方向</p></blockquote><blockquote><p>关联：正交三部曲（orthogonal-trilogy.md）、跨领域深度分析（orthogonal-cross-domain-analysis.md）、物理学（量子计算、黑洞）</p></blockquote>`,64)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
